steps.script:
$ErrorActionPreference='Continue'
$o=@{action='install_v2_shared_red_marks';state='failed';worker='ttactualidad-v2-private-test';v1_untouched=$true}
try {
 $url='https://raw.githubusercontent.com/fabricelop/europapress-rss/19b741b625f618c3df2253156e60e7f3b575131b/v2/private-worker/Install-Shared-Marks.ps1'
 $file=Join-Path $env:TEMP 'ttactualidad-v2-shared-marks-pinned.ps1'
 Invoke-WebRequest -UseBasicParsing -Uri $url -OutFile $file -TimeoutSec 30
 $src=Get-Content -LiteralPath $file -Raw
 if(!$src.Contains('ttactualidad-v2-marks') -or !$src.Contains('wrangler deploy --keep-vars') -or !$src.Contains('TT_V2_R_MARKS_REMOTE_READY=YES')){throw 'SOURCE_MISMATCH'}
 $out= & powershell.exe -NoProfile -NonInteractive -ExecutionPolicy Bypass -File $file 2>&1 | Out-String
 if($out.Contains('TT_V2_R_MARKS_REMOTE_READY=YES')){$o.state='deployed'}else{throw 'INSTALL_NOT_CONFIRMED'}
}catch{$o.error_class=$_.Exception.GetType().Name;$o.reason=$_.Exception.Message}
Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Compress))
